insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','night_audit','A guest''s card declines at 2 AM on a stayover. You:','A las 2 a. m. se rechaza la tarjeta de un huésped en estancia. Tú:','["Note it for the AM manager and follow the hotel''s credit policy", "Call the guest''s room to wake them", "Lock them out of the room right away"]'::jsonb,'["Anotarlo para el gerente de la mañana y seguir la política de crédito", "Llamar a la habitación para despertarlo", "Bloquearle la habitación de inmediato"]'::jsonb,0,'Don''t wake or lock out guests overnight for credit; follow policy and hand off.','No despiertes ni bloquees al huésped de noche por crédito; sigue la política y pásalo al turno de mañana.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','fire_panel','The fire alarm panel shows a ''trouble'' signal (not an alarm). You:','El panel de incendios muestra una señal de ''falla'' (no alarma). Tú:','["Unplug the panel", "Write down the zone/message and call the on-call manager or monitoring company", "Silence it and forget it"]'::jsonb,'["Desconectar el panel", "Anotar la zona y el mensaje y llamar al gerente de guardia o a la compañía de monitoreo", "Silenciarla y olvidarla"]'::jsonb,1,'A trouble signal means part of the system may not work. Report it right away.','Una falla significa que parte del sistema puede no funcionar. Repórtala de inmediato.','https://www.nfpa.org/education-and-research/home-fire-safety',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','fire_panel','The panel shows a fire ALARM in one zone. First step?','El panel muestra una ALARMA de incendio en una zona. ¿Primer paso?','["Reset the panel to stop the noise", "Wait 15 minutes", "Follow the emergency plan: call 911 and check the zone only if safe"]'::jsonb,'["Reiniciar el panel para parar el ruido", "Esperar 15 minutos", "Seguir el plan: llamar al 911 y revisar la zona solo si es seguro"]'::jsonb,2,'Never reset an alarm before the cause is known and the fire department says it''s OK.','Nunca reinicies una alarma antes de saber la causa y que los bomberos lo autoricen.','https://www.nfpa.org/education-and-research/home-fire-safety',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','security','Overnight, a non-guest asks to use the lobby restroom and stay in the lobby. You:','De noche, alguien que no es huésped quiere usar el baño y quedarse en el lobby. Tú:','["Leave the desk to argue", "Follow the overnight lobby policy and call police if you feel unsafe", "Give them a free room"]'::jsonb,'["Dejar la recepción para discutir", "Seguir la política nocturna del lobby y llamar a la policía si te sientes inseguro", "Darle una habitación gratis"]'::jsonb,1,'Your safety first. Know your hotel''s overnight access rules.','Tu seguridad primero. Conoce las reglas de acceso nocturno del hotel.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','security','Late at night the side entrance doors should be:','Tarde en la noche, las puertas laterales deben estar:','["Unlocked for deliveries", "Propped open for smokers", "Locked/key-card only, checked on your rounds"]'::jsonb,'["Abiertas para entregas", "Abiertas para los fumadores", "Cerradas o solo con tarjeta, revisadas en tus rondas"]'::jsonb,2,'Propped doors are a top overnight security risk.','Las puertas abiertas son un gran riesgo de seguridad de noche.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','cash','At the end of your shift your cash drawer is $5 short. You:','Al final de tu turno faltan $5 en la caja. Tú:','["Cover it from your pocket and say nothing", "Take it from petty cash", "Recount, report the exact amount honestly, and log it"]'::jsonb,'["Ponerlo de tu bolsillo sin decir nada", "Tomarlo de la caja chica", "Volver a contar, reportar la cantidad exacta con honestidad y registrarlo"]'::jsonb,2,'Honest over/short reports help find the cause.','Reportar con honestidad sobrantes y faltantes ayuda a encontrar la causa.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','cash','Someone calls overnight claiming to be from corporate asking you to buy gift cards or move money. You:','Alguien llama de noche diciendo ser de corporativo y te pide comprar tarjetas de regalo o mover dinero. Tú:','["Give them the safe code", "Do it quickly", "Hang up and tell your manager—it''s a common scam"]'::jsonb,'["Darle el código de la caja fuerte", "Hacerlo rápido", "Colgar y avisar a tu gerente; es una estafa común"]'::jsonb,2,'Real managers never ask for gift cards or cash by phone.','Un gerente real nunca pide tarjetas de regalo ni efectivo por teléfono.','https://consumer.ftc.gov/articles/avoiding-and-reporting-gift-card-scams',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','night_audit','Before the audit you find a room still showing ''due out'' that left. You:','Antes de la auditoría ves una habitación ''por salir'' que ya se fue. Tú:','["Leave it for tomorrow", "Check it out in the PMS and settle the folio per policy", "Delete the reservation"]'::jsonb,'["Dejarlo para mañana", "Hacer la salida en el sistema y cerrar la cuenta según la política", "Borrar la reserva"]'::jsonb,1,'Clean room statuses mean accurate reports and rooms for housekeeping.','Estados correctos dan reportes exactos y habitaciones para limpieza.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','night_audit','A no-show reservation should be:','Una reserva que no llegó (no-show) debe:','["Moved to tomorrow without notes", "Handled per the no-show policy (charge/cancel) before rolling the date", "Left in-house"]'::jsonb,'["Pasarse a mañana sin notas", "Manejarse según la política de no-show (cobrar o cancelar) antes de cerrar el día", "Dejarse como hospedada"]'::jsonb,1,'Check guarantees and policy first.','Revisa garantías y política primero.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','security','During overnight rounds you hear a loud fight in a room. You:','En tus rondas nocturnas escuchas una pelea fuerte en una habitación. Tú:','["Don''t enter; call 911 if anyone may be hurt, then the manager", "Ignore it", "Open the door with your key"]'::jsonb,'["No entres; llama al 911 si alguien puede estar herido y luego al gerente", "Ignorarlo", "Abrir la puerta con tu llave"]'::jsonb,0,'Don''t put yourself in danger. Police handle violence.','No te pongas en peligro. La policía maneja la violencia.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','night_audit','Why print or save backup reports (in-house list, arrivals) overnight?','¿Por qué imprimir o guardar reportes de respaldo (huéspedes, llegadas) de noche?','["They aren''t needed", "So the desk can work if the system or internet goes down", "For fun"]'::jsonb,'["No se necesitan", "Para trabajar si el sistema o el internet fallan", "Por diversión"]'::jsonb,1,'Backup reports are also key in an evacuation.','Los reportes de respaldo también son clave en una evacuación.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','security','A guest at 3 AM asks for a key but has no ID. You:','Un huésped a las 3 a. m. pide una llave pero no tiene identificación. Tú:','["Make it—it''s late", "Follow the no-ID policy (e.g., verify other details or escort) — don''t just make a key", "Give them the master key"]'::jsonb,'["Hacerla, es tarde", "Seguir la política sin identificación (verificar otros datos o acompañarlo); no hacer la llave sin más", "Darle la llave maestra"]'::jsonb,1,'Overnight is when key policy matters most.','De noche es cuando más importa la política de llaves.','general hospitality best practice',array['front_desk','night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','cash','A safe drop envelope should list:','El sobre del depósito en la caja fuerte debe indicar:','["Nothing", "Only your initials", "Date, shift, your name, and the counted amount"]'::jsonb,'["Nada", "Solo tus iniciales", "Fecha, turno, tu nombre y la cantidad contada"]'::jsonb,2,'Clear drops protect you.','Un depósito claro te protege.','general hospitality best practice',array['night_audit']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Which water temperature setting should you use?','¿Qué temperatura de agua debes usar?','["Always the hottest", "The one on the wash formula chart for that linen", "Always cold"]'::jsonb,'["Siempre la más caliente", "La de la tabla de fórmulas de lavado para esa ropa", "Siempre fría"]'::jsonb,1,'Formulas are set for clean results and fabric life.','Las fórmulas están hechas para limpiar bien y cuidar la tela.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Overloading a washer causes:','Sobrecargar una lavadora causa:','["Poor cleaning and machine damage", "Softer towels", "Faster washing"]'::jsonb,'["Mala limpieza y daño a la máquina", "Toallas más suaves", "Lavado más rápido"]'::jsonb,0,'Follow the load weight on the machine.','Sigue el peso de carga de la máquina.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','A towel still has a stain after washing. You:','Una toalla sigue manchada después de lavar. Tú:','["Send it up anyway", "Pull it for re-wash/stain treatment or rag it—never send it to a room", "Fold it with the stain hidden"]'::jsonb,'["Enviarla de todos modos", "Separarla para relavar o tratar, o usarla de trapo; nunca enviarla a una habitación", "Doblarla escondiendo la mancha"]'::jsonb,1,'Guests notice stains first.','Los huéspedes ven las manchas primero.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Why let linens finish the cool-down cycle in the dryer?','¿Por qué dejar que la ropa termine el ciclo de enfriamiento?','["Hot linens piled up can catch fire on their own", "To save time", "No reason"]'::jsonb,'["La ropa caliente amontonada puede incendiarse sola", "Para ahorrar tiempo", "Sin razón"]'::jsonb,0,'Oily, hot linens can self-heat. Never pile hot linens.','La ropa caliente con aceite puede calentarse sola. Nunca la amontones caliente.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Chemical dispensers on the washers: if one is empty or leaking you:','Si un dosificador de químicos de la lavadora está vacío o gotea:','["Pour bleach in by hand", "Report it; don''t pour chemicals in by hand unless trained", "Ignore it"]'::jsonb,'["Echar cloro a mano", "Reportarlo; no echar químicos a mano a menos que estés capacitado", "Ignorarlo"]'::jsonb,1,'Concentrated chemicals can burn skin and eyes.','Los químicos concentrados pueden quemar piel y ojos.','https://www.osha.gov/hazcom',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Folding towels to standard matters because:','Doblar toallas según el estándar importa porque:','["It doesn''t", "Rooms look consistent and carts stock faster", "It uses more towels"]'::jsonb,'["No importa", "Las habitaciones se ven iguales y los carritos se surten más rápido", "Usa más toallas"]'::jsonb,1,'Consistency is a brand standard.','La consistencia es un estándar de la marca.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','safety','Lifting a wet linen bag safely:','Levantar una bolsa de ropa mojada de forma segura:','["Drag it up the stairs", "Use a cart, keep it close, bend knees", "Swing it over your shoulder"]'::jsonb,'["Arrastrarla por las escaleras", "Usar un carrito, mantenerla cerca y doblar rodillas", "Echarla al hombro"]'::jsonb,1,'Wet linen is much heavier than dry.','La ropa mojada pesa mucho más que la seca.','https://www.cdc.gov/niosh/ergonomics/index.html',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Before washing, check pockets and linens for:','Antes de lavar, revisa bolsillos y ropa en busca de:','["Nothing", "Colors only", "Sharps, pens, and guest items"]'::jsonb,'["Nada", "Solo colores", "Objetos punzantes, plumas y artículos del huésped"]'::jsonb,2,'Pens ruin loads; sharps can hurt you. Log guest items.','Las plumas arruinan cargas; los objetos punzantes lastiman. Registra objetos del huésped.','https://www.osha.gov/bloodborne-pathogens',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Clean and dirty linen should be:','La ropa limpia y la sucia deben:','["Kept apart, in separate carts", "Stored on the floor", "Mixed on the same cart"]'::jsonb,'["Mantenerse separadas, en carritos distintos", "Guardarse en el piso", "Mezclarse en el mismo carrito"]'::jsonb,0,'Prevents re-contaminating clean linen.','Evita contaminar la ropa limpia.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Par stock for linen means:','El par de ropa de cama significa:','["The set number of linen sets the hotel keeps on hand", "One set per room", "The price of sheets"]'::jsonb,'["La cantidad fija de juegos que el hotel mantiene", "Un juego por habitación", "El precio de las sábanas"]'::jsonb,0,'Tell your supervisor when linen runs below par.','Avisa a tu supervisor cuando la ropa esté por debajo del par.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Torn or frayed sheets should be:','Las sábanas rotas o deshilachadas deben:','["Pulled and logged as discard/rag", "Put on a bed anyway", "Hidden in the closet"]'::jsonb,'["Retirarse y registrarse como descarte o trapo", "Ponerse en una cama de todos modos", "Esconderse en el clóset"]'::jsonb,0,'Logging discards helps order new linen in time.','Registrar descartes ayuda a pedir ropa a tiempo.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','The laundry room floor is wet. You:','El piso de la lavandería está mojado. Tú:','["Mop it and use a wet-floor sign", "Cover with towels", "Walk carefully and leave it"]'::jsonb,'["Trapearlo y poner letrero de piso mojado", "Taparlo con toallas", "Caminar con cuidado y dejarlo"]'::jsonb,0,'Slips are the top laundry injury.','Los resbalones son la lesión más común en lavandería.','https://www.osha.gov/walking-working-surfaces',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','A washer is making a loud banging noise. You:','Una lavadora hace un golpeteo fuerte. Tú:','["Sit on it", "Stop it if safe and put in a work order", "Keep running it"]'::jsonb,'["Sentarte encima", "Detenerla si es seguro y hacer una orden de trabajo", "Seguir usándola"]'::jsonb,1,'Off-balance loads can damage the machine.','Las cargas desbalanceadas dañan la máquina.','general hospitality best practice',array['hk_supervisor','laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','laundry','Mop heads and cleaning rags should be washed:','Los trapeadores y trapos de limpieza se lavan:','["Separately from guest linen", "With guest sheets", "Never"]'::jsonb,'["Por separado de la ropa de huéspedes", "Con las sábanas de huéspedes", "Nunca"]'::jsonb,0,'Keep guest linen clean.','Mantén limpia la ropa de huéspedes.','general hospitality best practice',array['laundry']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Restocking floor linen closets, you should:','Al surtir los clósets de piso, debes:','["Fill to par, rotate stock, keep it neat", "Fill only one floor", "Pile it on the floor"]'::jsonb,'["Llenar al par, rotar y mantenerlo ordenado", "Llenar solo un piso", "Apilarlo en el piso"]'::jsonb,0,'Room attendants lose time when closets are empty.','Los recamaristas pierden tiempo si los clósets están vacíos.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Trash and dirty linen from carts should be removed:','La basura y ropa sucia de los carritos se recoge:','["Once at the end of the day", "Only when asked", "Throughout the shift so carts don''t overflow"]'::jsonb,'["Una vez al final", "Solo si piden", "Durante todo el turno para que no se llenen"]'::jsonb,2,'Steady pickups keep hallways clear and safe.','Recoger seguido mantiene los pasillos libres y seguros.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Hallway vacuuming is best done:','Aspirar los pasillos es mejor:','["At times that don''t disturb sleeping guests", "At 6 AM by the rooms", "Never"]'::jsonb,'["En horarios que no molesten a los huéspedes que duermen", "A las 6 a. m. junto a las habitaciones", "Nunca"]'::jsonb,0,'Be mindful of quiet hours.','Respeta las horas de silencio.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','A guest asks you for extra towels. You:','Un huésped te pide toallas extra. Tú:','["Bring them promptly and with a smile", "Say you''re busy", "Tell them to call the desk"]'::jsonb,'["Llevarlas pronto y con una sonrisa", "Decir que estás ocupado", "Decirle que llame a recepción"]'::jsonb,0,'Quick requests make happy guests.','Atender rápido hace huéspedes felices.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','safety','Taking trash to the dumpster, watch for:','Al llevar basura al contenedor, cuida:','["Birds only", "Sharp items poking through bags—hold bags away from your body", "Nothing"]'::jsonb,'["Solo pájaros", "Objetos punzantes en las bolsas; sostenlas lejos del cuerpo", "Nada"]'::jsonb,1,'Never push trash down with your hands.','Nunca empujes la basura con las manos.','https://www.osha.gov/bloodborne-pathogens',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Cleaning public restrooms, the right PPE is:','Para limpiar baños públicos, el equipo correcto es:','["Gloves (and eye protection when spraying)", "None", "Only an apron"]'::jsonb,'["Guantes (y protección de ojos al rociar)", "Ninguno", "Solo un delantal"]'::jsonb,0,'Follow the label''s PPE.','Sigue el equipo indicado en la etiqueta.','https://www.osha.gov/hazcom',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','A spill on the stairwell at night. You:','Un derrame en la escalera de noche. Tú:','["Clean it right away and put up a sign", "Leave it for morning", "Cover with a rug"]'::jsonb,'["Limpiarlo de inmediato y poner un letrero", "Dejarlo para la mañana", "Taparlo con un tapete"]'::jsonb,0,'Stairs plus wet floors = serious falls.','Escaleras con piso mojado = caídas graves.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Lobby glass doors look smudged. You:','Las puertas de vidrio del lobby tienen manchas. Tú:','["Ignore", "Wait for a complaint", "Clean them—they''re the first thing guests see"]'::jsonb,'["Ignorar", "Esperar una queja", "Limpiarlas; es lo primero que ven los huéspedes"]'::jsonb,2,'First impressions count.','La primera impresión cuenta.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','In winter, the entrance and sidewalk need:','En invierno, la entrada y la banqueta necesitan:','["Nothing", "Snow cleared, ice melt, and dry mats", "Only a sign"]'::jsonb,'["Nada", "Quitar nieve, sal para hielo y tapetes secos", "Solo un letrero"]'::jsonb,1,'Minnesota ice is a top slip risk for guests.','El hielo de Minnesota es un gran riesgo de caídas.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Housekeeping carts should be parked:','Los carritos de limpieza se estacionan:','["In front of the elevator", "Across the hall", "Against the wall, not blocking exits or hallways"]'::jsonb,'["Frente al elevador", "Atravesados en el pasillo", "Contra la pared, sin bloquear salidas ni pasillos"]'::jsonb,2,'Keep exits clear at all times.','Mantén las salidas libres siempre.','https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/exit-routes',array['houseman','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','houseman','Pool area cleaning includes:','La limpieza del área de la piscina incluye:','["Wiping furniture, picking up towels, checking for glass", "Nothing", "Adding pool chemicals yourself"]'::jsonb,'["Limpiar muebles, recoger toallas y revisar vidrios", "Nada", "Agregar químicos tú mismo"]'::jsonb,0,'Leave pool chemicals to trained staff.','Deja los químicos de la piscina al personal capacitado.','general hospitality best practice',array['houseman']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','Making a bed, the standard is:','Al hacer una cama, el estándar es:','["Any way that looks OK", "Only a top sheet", "Tight, wrinkle-free, pillows placed per the brand photo"]'::jsonb,'["Como se vea bien", "Solo la sábana de arriba", "Tensa, sin arrugas y almohadas según la foto de la marca"]'::jsonb,2,'Use the brand''s room setup photo as your guide.','Usa la foto de la marca como guía.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','Hair in the tub after cleaning means:','Cabello en la tina después de limpiar significa:','["It''s fine", "The room is not ready—clean again", "Guests won''t notice"]'::jsonb,'["Está bien", "La habitación no está lista; limpia de nuevo", "No lo notarán"]'::jsonb,1,'Hair is one of the top guest complaints.','El cabello es una de las quejas más comunes.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','A stayover guest asks you not to change sheets. You:','Un huésped en estancia pide no cambiar las sábanas. Tú:','["Skip the room completely", "Change them anyway", "Respect it, tidy the room, and note it"]'::jsonb,'["No entrar a la habitación", "Cambiarlas de todos modos", "Respetarlo, arreglar la habitación y anotarlo"]'::jsonb,2,'Follow the guest''s choice and the hotel''s stayover policy.','Sigue la elección del huésped y la política de estancias.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','You run out of amenities on your cart mid-shift. You:','Se te acaban las amenidades del carrito. Tú:','["Take from another room", "Restock from the closet or call the houseman—don''t skip them", "Skip them"]'::jsonb,'["Tomarlas de otra habitación", "Surtir del clóset o llamar al houseman; no omitirlas", "Omitirlas"]'::jsonb,1,'Every room needs a full setup.','Toda habitación necesita su equipo completo.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','Why report a room you can''t finish on time?','¿Por qué avisar si no terminarás una habitación a tiempo?','["No reason", "So the supervisor can move rooms and you keep your points", "You''ll get in trouble"]'::jsonb,'["Sin razón", "Para que el supervisor mueva habitaciones y conserves tus puntos", "Te regañarán"]'::jsonb,1,'Early heads-up helps the whole team.','Avisar temprano ayuda a todo el equipo.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','safety','Spray cleaner near your face—best practice?','¿Rociar limpiador cerca de la cara? Buena práctica:','["Spray toward you", "Spray onto the cloth, not into the air", "Spray up high"]'::jsonb,'["Rociar hacia ti", "Rociar sobre el paño, no al aire", "Rociar hacia arriba"]'::jsonb,1,'Less mist in the air means less in your lungs and eyes.','Menos rocío en el aire es menos en tus pulmones y ojos.','https://www.osha.gov/hazcom',array['hk_supervisor','houseman','room_attendant']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','When inspecting a room, check first:','Al inspeccionar una habitación, revisa primero:','["The parking lot", "The closet ceiling", "What guests notice: bed, bathroom, hair, smell"]'::jsonb,'["El estacionamiento", "El techo del clóset", "Lo que notan los huéspedes: cama, baño, cabello, olor"]'::jsonb,2,'Inspect from the guest''s view, then coach kindly.','Inspecciona desde la vista del huésped y entrena con amabilidad.','general hospitality best practice',array['hk_supervisor']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','A room attendant fails an inspection item. Best coaching?','Un recamarista falla un punto de inspección. ¿Mejor manera de entrenar?','["Show them the fix in the room, privately and kindly", "Yell in the hallway", "Say nothing"]'::jsonb,'["Mostrarle cómo arreglarlo en la habitación, en privado y con amabilidad", "Gritar en el pasillo", "No decir nada"]'::jsonb,0,'Coach in private; praise in public.','Entrena en privado; reconoce en público.','general hospitality best practice',array['hk_supervisor']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','housekeeping','Assigning room boards fairly means:','Repartir habitaciones de forma justa significa:','["Random", "Giving friends the easy rooms", "Balancing checkouts, stayovers, and floors by minutes"]'::jsonb,'["Al azar", "Dar a amigos las fáciles", "Balancear salidas, estancias y pisos por minutos"]'::jsonb,2,'The app shows each person''s target minutes.','La app muestra los minutos meta de cada persona.','general hospitality best practice',array['hk_supervisor']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','A guest toilet is running constantly. Most common fix?','El inodoro de un huésped no deja de correr agua. ¿Arreglo más común?','["Replace the whole toilet", "Turn off water for the day", "Adjust or replace the flapper/fill valve"]'::jsonb,'["Cambiar todo el inodoro", "Cortar el agua todo el día", "Ajustar o cambiar el flapper o la válvula de llenado"]'::jsonb,2,'Running toilets waste a lot of water.','Un inodoro que corre desperdicia mucha agua.','general hospitality best practice',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','PTAC not cooling: first thing to check?','El PTAC no enfría: ¿qué revisas primero?','["Repaint it", "Order a new unit", "Filter and settings/breaker"]'::jsonb,'["Pintarlo", "Pedir uno nuevo", "El filtro y la configuración o el breaker"]'::jsonb,2,'Start simple: dirty filters cause many calls.','Empieza por lo simple: los filtros sucios causan muchas llamadas.','general hospitality best practice',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','A slow tub drain is usually caused by:','Un desagüe lento en la tina suele ser por:','["Hair buildup", "Too much water pressure", "The paint"]'::jsonb,'["Acumulación de cabello", "Mucha presión de agua", "La pintura"]'::jsonb,0,'Use a drain tool before harsh chemicals.','Usa una herramienta antes de químicos fuertes.','general hospitality best practice',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Before drilling into a wall, check for:','Antes de taladrar una pared, revisa:','["Hidden wires and pipes", "Paint color", "Nothing"]'::jsonb,'["Cables y tubos ocultos", "El color de la pintura", "Nada"]'::jsonb,0,'Use a stud/wire finder.','Usa un detector de cables y vigas.','https://www.osha.gov/electrical',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Door closers on guest room doors should:','Los cierrapuertas de las habitaciones deben:','["Slam the door", "Leave it slightly open", "Close and latch the door fully on their own"]'::jsonb,'["Azotar la puerta", "Dejarla un poco abierta", "Cerrar y asegurar la puerta solos por completo"]'::jsonb,2,'Self-closing doors are a fire and security safety feature.','Las puertas que cierran solas son una medida de seguridad contra incendios.','https://www.nfpa.org/education-and-research/home-fire-safety',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','The pool water looks cloudy. You:','El agua de la piscina se ve turbia. Tú:','["Add random chemicals", "Let guests swim", "Test chemistry, close the pool if unsafe, and log it"]'::jsonb,'["Agregar químicos al azar", "Dejar que naden", "Probar la química, cerrar si no es segura y registrarlo"]'::jsonb,2,'If you can''t see the bottom drain, close the pool.','Si no ves el desagüe del fondo, cierra la piscina.','https://www.cdc.gov/healthy-swimming/',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Keeping a parts stock (filters, flappers, bulbs) helps because:','Tener repuestos (filtros, flappers, focos) ayuda porque:','["It''s against policy", "It costs more", "Rooms get fixed the same day"]'::jsonb,'["Va contra la política", "Cuesta más", "Las habitaciones se reparan el mismo día"]'::jsonb,2,'Track parts in inventory and reorder at par.','Controla repuestos en inventario y pide al llegar al par.','general hospitality best practice',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Elevator stops between floors with a guest inside. You:','El elevador se detiene entre pisos con un huésped adentro. Tú:','["Reassure them, call the elevator company and 911 if needed—don''t force doors", "Pry the doors open", "Leave"]'::jsonb,'["Tranquilizarlo, llamar a la empresa del elevador y al 911 si hace falta; no forzar puertas", "Forzar las puertas", "Irte"]'::jsonb,0,'Only trained techs or firefighters free trapped riders.','Solo técnicos o bomberos rescatan a personas atrapadas.','general hospitality best practice',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Ice machine maintenance includes:','El mantenimiento de la máquina de hielo incluye:','["Only filling it", "Cleaning/sanitizing per the manufacturer and changing filters", "Nothing"]'::jsonb,'["Solo llenarla", "Limpiar y desinfectar según el fabricante y cambiar filtros", "Nada"]'::jsonb,1,'Ice is food—keep the machine clean.','El hielo es alimento; mantén limpia la máquina.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','maintenance','Snow and ice in the parking lot: when should it be treated?','Nieve y hielo en el estacionamiento: ¿cuándo tratarlos?','["Never", "Only when it melts", "Before guests arrive/leave and through the storm"]'::jsonb,'["Nunca", "Solo cuando se derrita", "Antes de llegadas y salidas y durante la tormenta"]'::jsonb,2,'Falls on ice are serious for guests and staff.','Las caídas en el hielo son graves para todos.','https://www.osha.gov/walking-working-surfaces',array['maintenance']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','food_safety','How often should you check and log buffet temperatures?','¿Cada cuánto revisas y registras las temperaturas del buffet?','["Never", "Once a week", "At set times during service, per your checklist"]'::jsonb,'["Nunca", "Una vez por semana", "En horarios fijos durante el servicio, según tu lista"]'::jsonb,2,'Logged temps prove food is safe.','Las temperaturas registradas prueban que la comida es segura.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','food_safety','Where should raw eggs or meat go in the fridge?','¿Dónde van los huevos crudos o la carne en el refrigerador?','["Bottom shelf, below ready-to-eat food", "Next to fruit", "Top shelf"]'::jsonb,'["En la repisa de abajo, debajo de lo listo para comer", "Junto a la fruta", "En la de arriba"]'::jsonb,0,'Drips from raw foods shouldn''t land on ready-to-eat food.','Los goteos de lo crudo no deben caer en lo listo para comer.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','food_safety','Opened milk or yogurt should be labeled with:','La leche o yogur abiertos se etiquetan con:','["The date opened/use-by date", "Nothing", "Your name only"]'::jsonb,'["La fecha de apertura o de uso", "Nada", "Solo tu nombre"]'::jsonb,0,'Date labels prevent serving old food.','Las fechas evitan servir comida vieja.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','breakfast','The coffee is almost empty at 7:30 AM. You:','El café casi se acaba a las 7:30 a. m. Tú:','["Wait until it''s empty", "Brew more before it runs out", "Put a sign"]'::jsonb,'["Esperar a que se acabe", "Hacer más antes de que se acabe", "Poner un letrero"]'::jsonb,1,'Coffee is the #1 breakfast item—never run out.','El café es lo más importante del desayuno; que nunca falte.','general hospitality best practice',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','breakfast','Greeting guests at breakfast:','Saludar a los huéspedes en el desayuno:','["Smile and say good morning—offer help", "Not needed", "Only if they talk first"]'::jsonb,'["Sonreír y dar los buenos días; ofrecer ayuda", "No es necesario", "Solo si hablan primero"]'::jsonb,0,'Breakfast sets the tone for the guest''s day.','El desayuno marca el tono del día del huésped.','general hospitality best practice',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','food_safety','Wiping cloths between uses should be:','Los paños entre usos deben:','["Left on the counter", "Kept in your pocket", "Kept in sanitizer solution"]'::jsonb,'["Dejarse en la barra", "Guardarse en tu bolsillo", "Guardarse en solución desinfectante"]'::jsonb,2,'Dirty cloths spread germs.','Los paños sucios propagan gérmenes.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','breakfast','A guest says the waffle maker is broken. You:','Un huésped dice que la wafflera está descompuesta. Tú:','["Check it, apologize, and report it/put a sign", "Tell them to skip waffles", "Ignore it"]'::jsonb,'["Revisarla, disculparte y reportarla o poner un letrero", "Decirle que no coma waffles", "Ignorarlo"]'::jsonb,0,'Fix fast or offer an alternative.','Repara rápido u ofrece una alternativa.','general hospitality best practice',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','food_safety','Can you use the hand sink to rinse dishes?','¿Puedes usar el lavamanos para enjuagar platos?','["Only when busy", "Yes", "No—hand sinks are only for handwashing"]'::jsonb,'["Solo si hay mucho trabajo", "Sí", "No, el lavamanos es solo para lavarse las manos"]'::jsonb,2,'Keep the hand sink clear and stocked.','Mantén el lavamanos libre y surtido.','https://www.fda.gov/food/fda-food-code/food-code-2022',array['breakfast']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','A guest asks you to stop somewhere not on the route. You:','Un huésped pide parar en un lugar fuera de ruta. Tú:','["Follow the hotel''s shuttle radius/policy and ask the manager if unsure", "Always yes", "Drive anywhere for a tip"]'::jsonb,'["Seguir la política y área del shuttle y preguntar al gerente si dudas", "Siempre sí", "Ir a donde sea por propina"]'::jsonb,0,'Policy keeps the schedule fair for all guests.','La política mantiene el horario justo para todos.','general hospitality best practice',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','Tire pressure should be checked:','La presión de las llantas se revisa:','["Once a year", "Never", "During your pre-trip, especially when temps drop"]'::jsonb,'["Una vez al año", "Nunca", "En tu revisión previa, sobre todo cuando baja la temperatura"]'::jsonb,2,'Cold Minnesota weather drops tire pressure.','El frío de Minnesota baja la presión de las llantas.','https://www.nhtsa.gov/road-safety',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','Snow on the van roof should be:','La nieve en el techo de la van debe:','["Cleared before driving", "Left on—it melts", "Only cleared from the windshield"]'::jsonb,'["Quitarse antes de manejar", "Dejarse; se derrite", "Quitarse solo del parabrisas"]'::jsonb,0,'Snow can slide onto the windshield or hit other cars.','La nieve puede caer al parabrisas o golpear otros autos.','https://dps.mn.gov/divisions/ots/winter-driving',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','A guest in a wheelchair needs a ride. You:','Un huésped en silla de ruedas necesita transporte. Tú:','["Say it''s not possible", "Follow the hotel''s accessible transport procedure and offer help", "Lift them without asking"]'::jsonb,'["Decir que no es posible", "Seguir el procedimiento de transporte accesible del hotel y ofrecer ayuda", "Cargarlo sin preguntar"]'::jsonb,1,'Always ask how the guest wants to be helped.','Siempre pregunta cómo quiere que lo ayudes.','https://www.ada.gov/topics/transportation/',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','Can you drive the shuttle after drinking any alcohol?','¿Puedes manejar el shuttle después de tomar alcohol?','["No—never drive after drinking", "Yes, after coffee", "Yes, one beer is fine"]'::jsonb,'["No, nunca manejes después de beber", "Sí, después de un café", "Sí, una cerveza está bien"]'::jsonb,0,'Zero alcohol behind the wheel at work.','Cero alcohol al volante en el trabajo.','https://www.nhtsa.gov/risky-driving/drunk-driving',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind) values ('all','all','driver','The check-engine or brake warning light comes on. You:','Se prende la luz de motor o de frenos. Tú:','["Ignore it", "Pull over safely if needed and report it before the next trip", "Cover the light"]'::jsonb,'["Ignorarla", "Detenerte de forma segura si hace falta y reportarlo antes del siguiente viaje", "Taparla"]'::jsonb,1,'Warning lights mean the van may be unsafe.','Las luces de alerta indican que la van puede no ser segura.','https://www.nhtsa.gov/road-safety',array['driver']::text[],'role') on conflict (brand,role_group,question_en) do update set roles=excluded.roles, kind=excluded.kind;
