create or replace function private.qotd_role(p_role text) returns text language sql immutable as $$
  select case p_role when 'front_desk' then 'front_desk' when 'hk_lead' then 'hk_supervisor' when 'housekeeper' then 'room_attendant'
    when 'laundry' then 'laundry' when 'house_person' then 'houseman' when 'maintenance' then 'maintenance' when 'breakfast' then 'breakfast'
    when 'shuttle_driver' then 'driver' when 'bartender' then 'bartender' else 'gm' end $$;
-- ~80% own-role, ~20% relevant shared; light brand question at most once per 7 days; spaced-repetition reviews first
create or replace function public.get_qotd() returns jsonb language plpgsql security definer set search_path=public,private as $$
declare u uuid := auth.uid(); h text; qr text; br text; d date := (now() at time zone 'America/Chicago')::date;
  row_ qotd_daily; qid bigint; rev boolean := false; qq qotd_questions; st user_stats; want text; light_ok boolean;
begin
  if u is null then raise exception 'sign in'; end if;
  select p.hotel_id, coalesce(p.qotd_role, private.qotd_role(p.role::text)) into h, qr from profiles p where p.user_id=u;
  select brand into br from hotels where id=h;
  select * into row_ from qotd_daily where user_id=u and day=d;
  if not found then
    select r.question_id into qid from qotd_review r join qotd_questions x on x.id=r.question_id and x.active and qr=any(x.roles)
      where r.user_id=u and r.due_date<=d order by r.due_date, random() limit 1;
    rev := qid is not null;
    if qid is null then
      light_ok := not exists (select 1 from qotd_daily y join qotd_questions x on x.id=y.question_id where y.user_id=u and y.day>d-7 and x.kind='brand_light');
      want := case when random()<0.8 then 'role' else 'shared' end;
      select x.id into qid from qotd_questions x where x.active and x.es_reviewed and x.brand in ('all',br) and qr=any(x.roles)
        and (x.kind<>'brand_light' or light_ok)
        and not exists (select 1 from qotd_daily y where y.user_id=u and y.question_id=x.id)
        order by case when x.kind=want or (want='shared' and x.kind='brand_light') then 0 else 1 end, random() limit 1;
    end if;
    if qid is null then
      select x.id into qid from qotd_questions x where x.active and x.es_reviewed and x.brand in ('all',br) and qr=any(x.roles) and x.kind<>'brand_light'
        order by (select max(day) from qotd_daily y where y.user_id=u and y.question_id=x.id) nulls first, random() limit 1;
    end if;
    if qid is null then return null; end if;
    insert into qotd_daily(user_id,day,hotel_id,question_id,role_group,is_review) values (u,d,h,qid,qr,rev) on conflict do nothing;
    select * into row_ from qotd_daily where user_id=u and day=d;
  end if;
  select * into qq from qotd_questions where id=row_.question_id;
  select * into st from user_stats where user_id=u;
  return jsonb_build_object('day',d,'question_id',qq.id,'topic',qq.topic,'is_review',row_.is_review,'role',qr,
    'question_en',qq.question_en,'question_es',qq.question_es,'options_en',qq.options_en,'options_es',qq.options_es,
    'answered',row_.answered_at is not null,'answered_idx',row_.answered_idx,'correct',row_.correct,
    'correct_idx',case when row_.answered_at is not null then qq.correct_idx end,
    'explain_en',case when row_.answered_at is not null then qq.explain_en end,
    'explain_es',case when row_.answered_at is not null then qq.explain_es end,
    'source_url',case when row_.answered_at is not null then qq.source_url end,
    'streak',coalesce(st.qotd_streak,0));
end $$;
create or replace function public.qotd_upsert(p_id bigint, p jsonb) returns bigint language plpgsql security definer set search_path=public,private as $$
declare id_ bigint;
begin
  if not (private.is_above() or private.my_role() in ('gm','agm')) then raise exception 'not allowed'; end if;
  if p_id is null and coalesce(jsonb_array_length(p->'roles'),0)=0 then raise exception 'pick at least one role'; end if;
  if p_id is null and coalesce(p->>'source_url','')='' then raise exception 'source_url required (use "general hospitality best practice" if none)'; end if;
  if p_id is null then
    insert into qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,es_reviewed,created_by,updated_by,roles,kind)
    values (coalesce(p->>'brand','all'),coalesce(p->>'role_group','all'),p->>'topic',p->>'question_en',p->>'question_es',p->'options_en',p->'options_es',
      (p->>'correct_idx')::int,p->>'explain_en',p->>'explain_es',p->>'source_url',coalesce((p->>'es_reviewed')::boolean,true),auth.uid(),auth.uid(),array(select jsonb_array_elements_text(p->'roles')),coalesce(p->>'kind','role')) returning id into id_;
  else
    update qotd_questions set brand=coalesce(p->>'brand',brand), role_group=coalesce(p->>'role_group',role_group), topic=coalesce(p->>'topic',topic),
      question_en=coalesce(p->>'question_en',question_en), question_es=coalesce(p->>'question_es',question_es),
      options_en=coalesce(p->'options_en',options_en), options_es=coalesce(p->'options_es',options_es),
      correct_idx=coalesce((p->>'correct_idx')::int,correct_idx), explain_en=coalesce(p->>'explain_en',explain_en), explain_es=coalesce(p->>'explain_es',explain_es),
      source_url=coalesce(p->>'source_url',source_url), es_reviewed=coalesce((p->>'es_reviewed')::boolean,es_reviewed), roles=coalesce(case when p ? 'roles' then array(select jsonb_array_elements_text(p->'roles')) end,roles), kind=coalesce(p->>'kind',kind),
      updated_by=auth.uid(), updated_at=now() where id=p_id returning id into id_;
  end if;
  return id_;
end $$;
